// The one thing this workflow will not invent is the idempotency key.
// Anything arriving over the internet eventually arrives twice; without a
// stable id per request, a redelivered enquiry becomes a second quote to the
// same customer for the same freight.
const body = $input.first().json.body ?? $input.first().json;

const messageId = body.messageId ?? body['message-id'] ?? body.Message_ID;
if (!messageId) {
  throw new Error('RFQ has no messageId — refusing rather than risking a duplicate quote');
}

const required = ['customerEmail', 'origin', 'destination', 'mode', 'incoterm'];
const missing = required.filter((k) => !body[k]);
if (missing.length) {
  throw new Error(`RFQ is missing: ${missing.join(', ')}`);
}

return [{
  json: {
    messageId: String(messageId),
    tenantId: $env.FREIGHT_TENANT_ID,
    customerEmail: String(body.customerEmail).trim().toLowerCase(),
    origin: String(body.origin).trim().toUpperCase(),
    destination: String(body.destination).trim().toUpperCase(),
    mode: String(body.mode).trim().toUpperCase(),
    containerType: body.containerType ?? null,
    quantity: Number(body.quantity ?? 1),
    incoterm: String(body.incoterm).trim().toUpperCase(),
    ...(body.consignment ? { consignment: body.consignment } : {}),
  },
}];
